-- cardak: generated by `cardak wezterm install`; reinstalling overwrites this file.
-- cardak-module: 5
-- Load it from wezterm.lua:  require('cardak').apply(config)
-- Without cardak's tab titles:  require('cardak').apply(config, { tab_titles = false })
-- Without the project backgrounds:  require('cardak').apply(config, { background = false })
local wezterm = require 'wezterm'

local M = {}

-- Project path -> name, scheme and background image, written next to this file by cardak (`cardak themes apply`,
-- or the deck whenever projects.toml changes). WezTerm reloads when it changes. Every project
-- is listed; one without a theme has no scheme.
local ok, data = pcall(require, 'cardak_projects')
if not ok or type(data) ~= 'table' then data = {} end
local default = type(data.default) == 'string' and data.default or nil
local opacity = data.background_opacity
if type(opacity) ~= 'number' or opacity <= 0 or opacity > 1 then opacity = 0.06 end

-- Every scheme cardak may set. An override holding any other scheme was set by someone
-- else (a light/dark toggle, say), and cardak leaves that window alone.
local ours = {}
if default then ours[default] = true end

-- A background is { file = <png>, cols = N, rows = N }: the art and its size in cells (#9).
local function image(b)
  if type(b) ~= 'table' or type(b.file) ~= 'string' then return nil end
  if type(b.cols) ~= 'number' or type(b.rows) ~= 'number' or b.cols < 1 or b.rows < 1 then
    return nil
  end
  return b
end

local projects = {}
for _, p in ipairs(type(data.projects) == 'table' and data.projects or {}) do
  if type(p) == 'table' and type(p.path) == 'string' then
    if type(p.scheme) ~= 'string' then p.scheme = nil end
    if type(p.name) ~= 'string' or p.name == '' then p.name = nil end
    p.background = image(p.background)
    if p.scheme or p.name or p.background then table.insert(projects, p) end
    if p.scheme then ours[p.scheme] = true end
  end
end
table.sort(projects, function(a, b) return #a.path > #b.path end) -- longest prefix wins

-- project path -> { scheme = …, background = <image>|false|nil } previewed from the deck's picker
local previews = {}
local backgrounds_on = true -- apply() turns it off for a user's own background
local base_opacity = 1 -- a translucent window (window_background_opacity) stays translucent

local function focus_target(id)
  local pane = wezterm.mux.get_pane(id)
  if not pane then return end
  local tab = pane:tab()
  if not tab then return end
  local win = tab:window()
  if not win then return end
  tab:activate()
  pane:activate()
  local gui = win:gui_window()
  if gui then gui:focus() end
end

local function cwd_path(pane)
  local cwd = pane:get_current_working_dir()
  if not cwd then return nil end
  if type(cwd) == 'userdata' then return cwd.file_path end -- Url object (20230712+)
  return (tostring(cwd):gsub('^file://[^/]*', ''))
end

local function under(path, root)
  return path == root or path:sub(1, #root + 1) == root .. '/'
end

-- Previews are keyed by the picker's project path, which may not be in `projects` yet
-- (a project without a theme, or a git repo being themed for the first time).
local function preview_for(path)
  local best, best_len = nil, -1
  for root, entry in pairs(previews) do
    if under(path, root) and #root > best_len then best, best_len = entry, #root end
  end
  return best
end

local function scheme_for(path, preview)
  if not path then return default end
  if preview and preview.scheme then return preview.scheme end
  for _, p in ipairs(projects) do
    if p.scheme and under(path, p.path) then return p.scheme end
  end
  return default
end

-- The innermost project's background: a nested project without one shows none.
local function background_for(path, preview)
  if not backgrounds_on or not path then return nil end
  if preview and preview.background ~= nil then return preview.background or nil end
  for _, p in ipairs(projects) do
    if under(path, p.path) then return p.background end
  end
  return nil
end

local builtin_schemes = nil
local function base_color(window, scheme)
  if scheme then
    builtin_schemes = builtin_schemes or wezterm.color.get_builtin_schemes()
    local s = builtin_schemes[scheme]
    if s and s.background then return s.background end
  end
  local ok, eff = pcall(function() return window:effective_config() end)
  local palette = ok and eff and eff.resolved_palette
  return palette and palette.background or 'black'
end

-- Setting `background` replaces the plain one, so the scheme's color is the first layer. Both
-- width and height must be in cells: either alone stretches the image (WezTerm 20240203).
local function layers(bg, base)
  return {
    { source = { Color = base }, width = '100%', height = '100%', opacity = base_opacity },
    {
      source = { File = bg.file }, opacity = opacity,
      repeat_x = 'NoRepeat', repeat_y = 'NoRepeat',
      horizontal_align = 'Right', vertical_align = 'Bottom',
      horizontal_offset = '-1cell', vertical_offset = '-1cell',
      width = bg.cols .. 'cell', height = bg.rows .. 'cell',
    },
  }
end

-- cardak's layers are known by their shape, not by memory: a config reload starts a fresh Lua
-- state while windows keep their overrides, so remembering "set by cardak" wouldn't survive it.
local function is_ours(b)
  if type(b) ~= 'table' or #b ~= 2 then return false end
  local base, img = b[1], b[2]
  return type(base) == 'table' and type(base.source) == 'table' and base.source.Color ~= nil
    and type(img) == 'table' and type(img.source) == 'table'
    and type(img.source.File) == 'string'
    and img.horizontal_align == 'Right' and img.vertical_align == 'Bottom'
end

local function shows(b)
  if b == nil then return nil end
  return table.concat({
    b[2].source.File, tostring(b[2].width), tostring(b[2].height), tostring(b[2].opacity),
    tostring(b[1].source.Color), tostring(b[1].opacity),
  }, '|')
end

-- Sets overrides.background; true when it changed. One cardak didn't set is left alone.
local function sync_background(window, overrides, path, preview, scheme)
  if overrides.background ~= nil and not is_ours(overrides.background) then return false end
  local bg = background_for(path, preview)
  local want = bg and layers(bg, base_color(window, scheme)) or nil
  if shows(want) == shows(overrides.background) then return false end
  overrides.background = want
  return true
end

local function sync(window)
  local pane = window:active_pane()
  if not pane then return end
  local path = cwd_path(pane)
  local preview = path and preview_for(path)
  local scheme = scheme_for(path, preview)
  local overrides = window:get_config_overrides() or {}
  local current = overrides.color_scheme
  if current ~= nil and not ours[current] then return end
  local changed = sync_background(window, overrides, path, preview, scheme)
  if current ~= scheme then
    overrides.color_scheme = scheme
    changed = true
  end
  if changed then window:set_config_overrides(overrides) end
end

-- Tab titles (module 4): "<project> · <pane title>", the project as the deck names it: the
-- configured one, else the git repository's directory. Elsewhere, and for a title the user set,
-- WezTerm's own title. format-tab-title runs on the GUI thread at every redraw, so the git
-- lookup (a stat per directory up the tree) is cached per directory; "no repository" only for
-- GIT_RETRY_S, so a `git init` or clone in an open tab gets its name.
local GIT_RETRY_S = 30
local git_names, git_cached = {}, 0 -- path -> name, or the os.time() a lookup found none

local function exists(path)
  local f = io.open(path, 'r') -- opens a directory too, and a worktree's .git is a file
  if not f then return false end
  f:close()
  return true
end

local function git_name(path)
  path = path:gsub('/+$', '')
  local cached = git_names[path]
  if type(cached) == 'string' then return cached end
  if cached and os.time() - cached < GIT_RETRY_S then return nil end
  local found, dir = nil, path
  while dir ~= '' do
    if exists(dir .. '/.git') then
      found = dir:match('([^/]+)$')
      break
    end
    dir = dir:match('^(.*)/[^/]*$') or ''
  end
  if git_cached >= 256 then git_names, git_cached = {}, 0 end
  git_names[path], git_cached = found or os.time(), git_cached + 1
  return found
end

local function project_name(path)
  for _, p in ipairs(projects) do
    if p.name and under(path, p.path) then return p.name end
  end
  return git_name(path)
end

local function info_cwd(pane)
  local cwd = pane.current_working_dir
  if not cwd then return nil end
  if type(cwd) == 'userdata' then return cwd.file_path end -- Url object (20230712+)
  return (tostring(cwd):gsub('^file://[^/]*', ''))
end

local function tab_title(tab, config, max_width)
  if tab.tab_title and tab.tab_title ~= '' then return nil end -- set by the user
  local pane = tab.active_pane
  local path = pane and info_cwd(pane)
  local name = path and path ~= '' and project_name(path)
  if not name then return nil end
  local text = name
  if pane.title and pane.title ~= '' and pane.title ~= name then
    text = name .. ' · ' .. pane.title
  end
  if config.show_tab_index_in_tab_bar ~= false then
    local base = config.tab_and_split_indices_are_zero_based and 0 or 1
    text = (tab.tab_index + base) .. ': ' .. text
  end
  return ' ' .. wezterm.truncate_right(text, math.max(max_width - 2, 1)) .. ' '
end

-- Focus history (module 3): which pane the user is looking at, for the deck's "seen" and
-- the hook's "don't ping, they're already here". The file keeps the last 64 changes:
--   # cardak-focus: 1
--   <pane_id|none> <unix_ms>
local FOCUS_HEADER = '# cardak-focus: 1'
local FOCUS_KEEP = 64
local focus_file = (os.getenv('XDG_STATE_HOME') or ((os.getenv('HOME') or '') .. '/.local/state'))
  .. '/cardak/focus'
local focus_history, focus_last, focus_window = {}, nil, nil

local function load_focus_history()
  local f = io.open(focus_file, 'r')
  if not f then return end
  local first = true
  for line in f:lines() do
    if first then
      first = false
      if line ~= FOCUS_HEADER then break end
    elseif line:match('^%S+ %d+$') then
      table.insert(focus_history, line)
    end
  end
  f:close()
  while #focus_history > FOCUS_KEEP do table.remove(focus_history, 1) end
  if #focus_history > 0 then focus_last = focus_history[#focus_history]:match('^(%S+)') end
end

local function now_ms()
  local ok, ms = pcall(function() return tonumber(wezterm.time.now():format('%s%3f')) end)
  if ok and ms then return math.floor(ms) end
  return os.time() * 1000
end

-- Each GUI process writes through its own tmp file, so two GUIs never write one half-finished
-- file; the history itself is shared, last writer wins.
local function tmp_name()
  local ok, pid = pcall(function() return wezterm.procinfo.pid() end)
  return focus_file .. '.tmp' .. ((ok and pid) and ('.' .. pid) or '')
end

local function write_focus_history()
  local tmp = tmp_name()
  local f = io.open(tmp, 'w')
  if not f then return end -- no state dir yet: cardak creates it on first use
  f:write(FOCUS_HEADER, '\n', table.concat(focus_history, '\n'), '\n')
  f:close()
  os.rename(tmp, focus_file)
end

local function report_focus(window)
  local value
  if window:is_focused() then
    focus_window = window:window_id()
    local pane = window:active_pane()
    if not pane then return end
    value = tostring(pane:pane_id())
  elseif focus_window == window:window_id() then
    focus_window = nil
    value = 'none'
  else
    return -- another, unfocused window: nothing to say
  end
  if value == focus_last then return end
  focus_last = value
  table.insert(focus_history, value .. ' ' .. now_ms())
  while #focus_history > FOCUS_KEEP do table.remove(focus_history, 1) end
  write_focus_history()
end

pcall(load_focus_history)

local function sync_all()
  for _, w in ipairs(wezterm.gui.gui_windows()) do pcall(sync, w) end
end

-- cardak_focus=<pane_id>:<nonce> raises a pane's window (M2).
-- cardak_preview={"path": …, "scheme": …, "background": …, "n": …} previews (or, with "",
-- clears) a scheme, and with "background" (an image, or false) the project's background.
-- Both are set by the deck on its own pane; the nonce makes every request a change.
local function on_user_var(_, _, name, value)
  if name == 'cardak_focus' then
    local id = tonumber(value:match('^(%d+)'))
    if id then pcall(focus_target, id) end
  elseif name == 'cardak_preview' then
    local okp, req = pcall(wezterm.json_parse, value)
    if not okp or type(req) ~= 'table' or type(req.path) ~= 'string' then return end
    if type(req.scheme) == 'string' and req.scheme ~= '' then
      local bg = req.background
      if bg ~= false then bg = image(bg) end
      previews[req.path] = { scheme = req.scheme, background = bg }
      ours[req.scheme] = true
    else
      previews[req.path] = nil
    end
    pcall(sync_all)
  end
end

local function window_opacity(config)
  local ok, value = pcall(function() return config.window_background_opacity end)
  if ok and type(value) == 'number' and value > 0 and value <= 1 then return value end
  return 1
end

local function users_background(config)
  local ok, set = pcall(function()
    return config.background ~= nil or config.window_background_image ~= nil
  end)
  return ok and set
end

function M.apply(config, opts)
  backgrounds_on = not (type(opts) == 'table' and opts.background == false)
    and not (type(config) == 'table' and users_background(config))
  base_opacity = type(config) == 'table' and window_opacity(config) or 1
  wezterm.on('user-var-changed', on_user_var)
  if not (type(opts) == 'table' and opts.tab_titles == false) then
    -- WezTerm runs only the first format-tab-title handler registered
    wezterm.on('format-tab-title', function(tab, _, _, cfg, _, max_width)
      local ok, title = pcall(tab_title, tab, cfg, max_width)
      if ok then return title end
    end)
  end
  wezterm.on('update-status', function(window)
    pcall(sync, window)
    pcall(report_focus, window)
  end)
  wezterm.on('window-focus-changed', function(window) pcall(report_focus, window) end)
  return config
end

return M
